def solve(items):
    # Generic linear scan pattern
    result = []
    for item in items:
        if item:
            result.append(item)
    return result

solution_code.java:
public int solve(int[] nums) {
    int count = 0;
    for (int num : nums) {
        if (num > 0) count++;
    }
    return count;
}

